/** A suggestion only when the user wants deleted content, not a recovery step. */
export const foregroundStorageRecoveryNote = 'Storage authority and deleted content: In Local mode, the current local records are authoritative. Recreated empty structures do not recover deleted text. In Git mode, if the user wants deleted content back, you may suggest checking the repository history. Do not search history or restore content automatically, or make either a prerequisite for initialization or continuing work.'

// The complete original Foreground rules are generated into authoritative storage.
// Keep their original wording and order here; the short prompt only supplies the entry point.
export function foregroundFullGuide(): string {
  return foregroundWakePriority + '\n\n' + shared('Foreground') + '\n\n' + prompts.Foreground + '\n\n' + foregroundStorageRecoveryNote + '\n\n' + materialLinksPrompt
}

export function frameworkRolePrompt(role: RecoveryRole): string {
  if (role === 'Foreground') return foregroundCorePrompt
  if (role === 'Worker' || role === 'Recorder') return prompts[role]
  return shared(role) + '\n\n' + mechanical + '\n\n' + prompts[role] }
